import XCTest
import UIKit

// Drives WebnovelReader into a playing state, then opens Safari to a local
// (data: URI, no network needed) HTML page with a silent <audio> element.
// Tapping PLAY makes WebKit request the shared AVAudioSession — a real
// .began interruption on our app's .playback session, exactly like Maps/
// alarms/calls do. Terminating Safari afterward forces a real .ended
// (shouldResume) interruption. Proves AudioPlaybackService.onInterruptionBegan/
// onInterruptionEnded (routed through ReaderPlaybackController.remotePause()/
// remotePlay()) actually resume playback with no user tap, instead of the
// pre-fix behavior where the app stayed silently paused forever.
final class AudioInterruptionUITests: XCTestCase {

    private static let audioPageDataURI = """
data:text/html;base64,
"""

    override func setUpWithError() throws {
        continueAfterFailure = false
    }

    private func waitForLabel(_ button: XCUIElement, _ label: String, timeout: TimeInterval = 15, message: String) {
        let predicate = NSPredicate(format: "label == %@", label)
        let expectation = XCTNSPredicateExpectation(predicate: predicate, object: button)
        XCTAssertEqual(XCTWaiter().wait(for: [expectation], timeout: timeout), .completed, message)
    }

    func testInterruptionAutoResumesPlayback() throws {
        let app = XCUIApplication()
        app.launch()

        let bookRow = app.buttons["bookRow"].firstMatch
        if bookRow.waitForExistence(timeout: 10) {
            bookRow.tap()
            let startButton = app.buttons["startFromBeginningButton"]
            if startButton.waitForExistence(timeout: 5) {
                startButton.tap()
            }
        }
        let playPauseButton = app.buttons["playPauseButton"]
        XCTAssertTrue(playPauseButton.waitForExistence(timeout: 15), "Should reach ReaderView")
        playPauseButton.tap()
        waitForLabel(playPauseButton, "Tạm dừng", message: "Playback should start playing before the interruption test begins")

        UIPasteboard.general.string = Self.audioPageDataURI

        let safari = XCUIApplication(bundleIdentifier: "com.apple.mobilesafari")
        safari.launch()
        let addressField = safari.textFields["TabBarItemTitle"]
        XCTAssertTrue(addressField.waitForExistence(timeout: 10))
        addressField.tap()
        // Tapping swaps in the actual edit-mode field — a different
        // accessibility identifier ('URL') from the collapsed tab-bar title
        // ('TabBarItemTitle') tapped above.
        let editingURLField = safari.textFields["URL"]
        XCTAssertTrue(editingURLField.waitForExistence(timeout: 5))
        // On Simulator, long-pressing an empty text field with pasteboard
        // content pastes immediately — no "Paste" callout menu ever
        // appears (unlike a real device), so there's nothing further to
        // tap here before hitting Go.
        editingURLField.press(forDuration: 1.2)
        XCTAssertTrue(
            NSPredicate(format: "value BEGINSWITH %@", "data:text/html").evaluate(with: editingURLField),
            "Long-press should have pasted the data URI into the address field"
        )
        let goButton = safari.keyboards.buttons["Go"]
        XCTAssertTrue(goButton.waitForExistence(timeout: 5))
        sleep(1)
        goButton.tap()

        let playHTMLButton = safari.buttons["PLAY"]
        XCTAssertTrue(playHTMLButton.waitForExistence(timeout: 30), "data: URI page should load with a PLAY button")
        playHTMLButton.tap()

        // Give WebKit a moment to actually request the audio session —
        // AudioPlaybackService.onInterruptionBegan fires asynchronously off
        // the AVAudioSession.interruptionNotification.
        sleep(2)

        app.activate()
        waitForLabel(playPauseButton, "Đọc", timeout: 10, message: "App audio should be paused by Safari's interruption (.began)")

        // Terminating Safari (rather than tapping STOP, which only pauses
        // the element without necessarily deactivating the session) forces
        // a clean, real .ended interruption with .shouldResume.
        safari.terminate()

        app.activate()
        waitForLabel(playPauseButton, "Tạm dừng", timeout: 10, message: "App should auto-resume once Safari's interruption ends, with no user tap")
    }
}
